<?php
$root=dirname(__DIR__);$dir=$root.'/storage';if(!is_dir($dir))mkdir($dir,0775,true);$path=$dir.'/install.key';if(is_file($path)){echo "Ya existe un código de instalación: ".trim(file_get_contents($path)).PHP_EOL;exit;} $key=strtoupper(substr(bin2hex(random_bytes(12)),0,4).'-'.substr(bin2hex(random_bytes(12)),0,4).'-'.substr(bin2hex(random_bytes(12)),0,4).'-'.substr(bin2hex(random_bytes(12)),0,4));file_put_contents($path,$key);@chmod($path,0600);echo "Código de instalación: $key".PHP_EOL;echo "Se invalidará automáticamente después de crear el primer administrador.".PHP_EOL;
